curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"{ __schema { queryType { fields { name args { name type { name kind ofType { name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if f['name'] in ('searchDocuments','documents','document','searchProjects'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ', a['name'], t['kind'], t.get('name') or t.get('ofType'))
"

